window.AUTH=window.AUTH||{};window.AUTH["24-316"]={"d":"24-316","id":"2024/24-316","n":"Kennedy v. Braidwood Management, Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioners Robert F. Kennedy, Jr., et al.","date":"2025-02-18","url":"https://www.supremecourt.gov/DocketPDF/24/24-316/343079/20250218171629934_24-316tsUnitedStates.pdf","side":"pet","n":49},{"k":"respondent","label":"Brief of respondents Braidwood Management, Inc., et al.","date":"2025-03-20","url":"https://www.supremecourt.gov/DocketPDF/24/24-316/352648/20250320173752027_Respondent%20Brief%20on%20the%20Merits.pdf","side":"res","n":67},{"k":"reply","label":"Reply of petitioners Robert F. Kennedy, Jr., Secretary of Health and Human Services, et al.","date":"2025-04-11","url":"https://www.supremecourt.gov/DocketPDF/24/24-316/355333/20250411113746733_24-316rbUnitedStates.pdf","side":"pet","n":35}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/606us2r65_3314.pdf","tr":true,"items":[{"t":"case","label":"Bandimere v. SEC","cite":"844 F.3d 1168","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/844/1168/","by":{"0":"34"}},{"t":"case","label":"Barr v. American Ass’n of Political Consultants, Inc.","cite":"591 U.S. 610","y":2020,"id":"2019/19-631","sc":1,"op":1,"sum":"The Court held that a provision of the Telephone Consumer Protection Act of 1991 creating an exception to the prohibition on automated calls for government debt collection calls violates the First Amendment but is severable from the remainder of the statute.","sumSrc":"Oyez","by":{"0":"39, 44","1":"54","2":"2, 22, 23"}},{"t":"case","label":"Bowsher v. Synar","cite":"478 U.S. 714","y":1986,"id":"1985/85-1377","sc":1,"op":1,"sum":"The Court found that the duties which the Congress delegated to the Comptroller General did violate the doctrine of separation of powers and were unconstitutional. A two step process led Chief Justice Burger to arrive at this conclusion.","sumSrc":"Oyez","by":{"0":"20, 21, 23","1":"17"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":"36","1":"5, 9, 51, 54"}},{"t":"case","label":"CFPB v. Community Fin. Servs. Ass’n of Am., Ltd","cite":"601 U.S. 416","y":2024,"id":"2023/22-448","sc":1,"sum":"Congress’ statutory authorization allowing the Consumer Financial Protection Bureau to draw money from the earnings of the Federal Reserve System to carry out the Bureau’s duties, 12 U. S. C. §§5497(a)(1), (2), satisfies the Appropriations Clause.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"Collins v. Yellen","cite":"594 U.S. 220","y":2021,"id":"2020/19-422","sc":1,"op":15,"ar":2,"sum":"Because the Federal Housing Finance Agency (FHFA) did not exceed its authority under the Housing and Economic Recovery Act of 2008 as a conservator of Fannie Mae and Freddie Mac, the anti-injunction provisions of the Recovery Act bar the statutory claim brought by shareholders of those entities; the Recovery Act’s structure, which restricts the President’s power to remove the FHFA Director, violates the separation of powers.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"26","1":"21","2":"2, 4, 5, 21, 22"}},{"t":"case","label":"Edmond v. United States","cite":"520 U.S. 651","y":1997,"id":"1996/96-262","sc":1,"op":31,"ar":4,"sum":"Holding that the power to “assign” military judges is not the power to “appoint” them, because “Congress has consistently used the word `appoint' ” to vest appointment power for “military positions”.","sumSrc":"opinion","by":{"0":"2, 3, 14, 15, 17, 20-22, 30, 35, 37, 38","1":"6, 8, 9, 13, 17, 22–23, 23, 43, 44","2":"1, 3, 6, 9, 13, 15, 16, 18"}},{"t":"case","label":"Federal Open Mkt. Comm. of the Fed. Reserve Sys. v. Merrill","cite":"443 U.S. 340","y":1979,"id":"1978/77-1387","sc":1,"sum":"This case presents the question whether the Freedom of Information Act (FOIA) is violated by petitioner's practice, authorized by regulation, 12 CFR § 271.5 (1978), of withholding certain monetary policy directives from the public during the month they are in effect, such directives being published in full in the Federal Register at the end of the month. To implement its authority to conduct open market operations …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Free Enter. Fund v. Public Co. Accounting Oversight Bd.: 537 F.3d 667 (D.C. Cir. 2008), aff ’d in part, rev’d in part, and remanded","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"op":8,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"15, 21, 23, 27","1":"16, 21, 52, 54","2":"6, 7"}},{"t":"case","label":"Freytag v. Commissioner","cite":"501 U.S. 868","y":1991,"id":"1990/90-762","sc":1,"op":2,"sum":"On the question of whether 7443A permitted the assignment of complex cases to special trial judges, the Supreme Court unanimously ruled that the statute unambiguously did allow such appointments. Justice Harry Blackmun, in the majority opinion, wrote, \"The plain language of 7443A(b)(4) surely authorizes the Chief Judge's assignment of petitioners' cases to a special trial judge.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Intercollegiate Broad. Sys., Inc. v. Copyright Royalty Bd.","cite":"684 F.3d 1332","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/684/1332/","op":1,"by":{"0":"21"}},{"t":"case","label":"Kalaris v. Donovan","cite":"697 F.2d 376","y":1983,"url":"https://www.courtlistener.com/c/F.2d/697/376/","sum":"Holding that members of the Benefits Review Board in the Department of Labor, who issue final benefits-related orders that are not subject to superior-officer review, are “inferior officers” who serve “at the discretion of their appointing officer”.","sumSrc":"brief:0","by":{"0":"25"}},{"t":"case","label":"Loeb v. Columbia Township Trustees","cite":"179 U.S. 472","y":1900,"id":"scdb/1900-050","sc":1,"sum":"In a case brought here from a Circuit Court, the opinion regularly filed below, and which has been annexed to and transmitted with the record, may be examined in order to ascertain, in cases like this, whether either party, claimed that a state statute upon which the judgment necessarily depended, in whole or in part was in contravention of the Constitution of the United States; but this must not be understood as …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Lucia v. SEC","cite":"585 U.S. 237","y":2018,"url":"https://supreme.justia.com/cases/federal/us/585/237/","sc":1,"op":5,"sum":"Explaining that the Securities and Exchange Commission may “review the [Administrative Law Judge’s] decision”.","sumSrc":"brief:0","by":{"0":"2, 33","1":"5, 45"}},{"t":"case","label":"Massachusetts v. Mellon","cite":"262 U.S. 447","y":1923,"id":"1900-1940/262us447","sc":1,"op":1,"sum":"The Court held that the administration of federal statutes \"likely to produce addition taxation to be imposed upon a vast number of taxpayers\" was essentially a matter of public and not of individual concern.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Myers v. United States","cite":"272 U.S. 52","y":1926,"id":"1900-1940/272us52","sc":1,"op":3,"sum":"After tracing legislative debate of the First Congress in 1789 which dealt with the interpretation of the President's appointment power, Chief Justice Taft concluded that the power to remove appointed officers is vested in the President alone. According to Taft, to deny the President that power would not allow him to \"discharge his own constitutional duty of seeing that the laws be faithfully executed.\".","sumSrc":"Oyez","by":{"0":"26, 38","1":"24, 43","2":"5"}},{"t":"case","label":"Reagan v. United States","cite":"182 U.S. 419","y":1901,"id":"scdb/1900-066","sc":1,"op":2,"sum":"In 1896, commissioners appointed by judges of the United States Court in the Indian Territory were inferior officers, not holding their offices for life, or by any fixed tenure, but subject to removal by the appointing power.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27","1":"22"}},{"t":"case","label":"Seila Law LLC v. CFPB","cite":"591 U.S. 197","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/197/","sc":1,"op":3,"ar":1,"by":{"0":"45","1":"16, 21, 54","2":"5, 21-23"}},{"t":"case","label":"Silver v. United States Postal Serv.","cite":"951 F.2d 1033","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/951/1033/","sum":"Concluding that the Postmaster General, “[t]he chief executive officer of the Postal Service,” 39 U.S.C. 203, is an inferior officer under the Appointments Clause because he “serv[es] at the pleasure of the” Postal Service’s Board of Governors.","sumSrc":"brief:0","by":{"0":"25"}},{"t":"case","label":"Turkiye Halk Bankasi A.S. v. United States","cite":"598 U.S. 264","y":2023,"id":"2022/21-1450","sc":1,"sum":"The District Court has jurisdiction of this criminal prosecution under 18 U. S. C. §3231, and the Foreign Sovereign Immunities Act’s comprehensive scheme governing claims of immunity in civil actions against foreign states and their instrumentalities does not cover criminal cases.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"33"}},{"t":"case","label":"United States v. Arthrex, Inc.","cite":"594 U.S. 1","y":2021,"id":"2020/19-1434","sc":1,"op":18,"ar":10,"sum":"The unreviewable authority wielded by Administrative Patent Judges during inter partes review is incompatible with their appointment by the Secretary of Commerce to an inferior office; the judgment of the Federal Circuit is vacated, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"2, 4, 10, 14, 15, 18, 20-22, 26, 27, 30, 33-37, 39-41, 45","1":"54","2":"2, 6, 7, 9, 13, 16, 20-22"}},{"t":"case","label":"United States v. Germaine","cite":"99 U.S. 508","y":1879,"id":"scdb/1878-198","sc":1,"op":3,"sum":"Holding that Congress cannot vest the appointment power by conferring it on offcials who are “the mere aids and subordinates of the heads of the departments”.","sumSrc":"opinion","by":{"0":"2"}},{"t":"const","label":"Article II, Section 2, Clause 2","clauses":[["appointments","Appointments Clause"]],"text":"He shall have Power, by and with the Advice and Consent of the Senate, to make Treaties, provided two thirds of the Senators present concur; and he shall nominate, and by and with the Advice and Consent of the Senate, shall appoint Ambassadors, other public Ministers and Consuls, Judges of the supreme Court, and all other Officers of the United States, whose Appointments are not herein otherwise provided for, and which shall be established by Law: but the Congress may by Law vest the Appointment of such inferior Officers, as they think proper, in the President alone, in the Courts of Law, or in the Heads of Departments.","by":{"0":"24"}},{"t":"law","label":"Pub. L. No. 98-532","url":"https://www.govinfo.gov/link/statute/98/2705","by":{"0":"7"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)","(1)","(2)(A)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"0":"9, 11","1":"49, 49, 33"}},{"t":"law","label":"Federal Advisory Committee Act, Pub. L. No. 92-463","url":"https://www.govinfo.gov/link/statute/86/770","by":{"0":"43"}},{"t":"law","label":"Pub. L. No. 106-129","url":"https://www.govinfo.gov/link/plaw/106/public/129","by":{"0":"5"}},{"t":"law","label":"Patient Protection and Affordable Care Act, Pub. L. No. 111-148","url":"https://www.govinfo.gov/link/plaw/111/public/148","by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 300gg-13","url":"https://www.law.cornell.edu/uscode/text/42/300gg-13","subs":["(a)(1)","(a)(2)","(b)(1)","(b)(2)","(a)","(b)","(a)(3)","(a)(4)"],"stext":{"head":"§300gg–13. Coverage of preventive health services","paras":[[0,"(a) In general"],[0,"A group health plan and a health insurance issuer offering group or individual health insurance coverage shall, at a minimum provide coverage for and shall not impose any cost sharing requirements for—"],[1,"(1) evidence-based items or services that have in effect a rating of \"A\" or \"B\" in the current recommendations of the United States Preventive Services Task Force;"],[1,"(2) immunizations that have in effect a recommendation from the Advisory Committee on Immunization Practices of the Centers for Disease Control and Prevention with respect to the individual involved; and 1"],[1,"(3) with respect to infants, children, and adolescents, evidence-informed preventive care and screenings provided for in the comprehensive guidelines supported by the Health Resources and Services Administration.1"],[1,"(4) with respect to women, such additional preventive care and screenings not described in paragraph (1) as provided for in comprehensive guidelines supported by the Health Resources and Services Administration for purposes of this paragraph.1"],[1,"(5) for the purposes of this chapter, and for the purposes of any other provision of law, the current recommendations of the United States Preventive Service Task Force regarding breast cancer screening, mammography, and prevention shall be considered the most current other than those issued in or around November 2009."],[0,"Nothing in this subsection shall be construed to prohibit a plan or issuer from providing coverage for services in addition to those recommended by United States Preventive Services Task Force or to deny coverage for services that are not recommended by such Task Force."],[0,"(b) Interval"],[0,"(1) In general"],[1,"The Secretary shall establish a minimum interval between the date on which a recommendation described in subsection (a)(1) or (a)(2) or a guideline under subsection (a)(3) is issued and the plan year with respect to which the requirement described in subsection (a) is effective with respect to the service described in such recommendation or guideline."],[0,"(2) Minimum"],[1,"The interval described in paragraph (1) shall not be less than 1 year."],[0,"(c) Value-based insurance design"],[0,"The Secretary may develop guidelines to permit a group health plan and a health insurance issuer offering group or individual health insurance coverage to utilize value-based insurance designs."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/300gg-13?type=usc&year=mostrecent&link-type=html"},"head":"§300gg–13. Coverage of preventive health services","tname":"The Public Health and Welfare","by":{"0":"29, 29, 29, 29, 29","1":"26, 27, 28, 32, 39, 40, i, 2, i, 2, 4, 7, 10, 12, 13, 24, 25, 28, 30, 42, 46, 53, 54, 2, 2, 28, 36, 33, 34","2":"22, 11-14, 20, 20, 12, 1, 18, 14, 9"}},{"t":"usc","label":"42 U.S.C. § 300gg-92","url":"https://www.law.cornell.edu/uscode/text/42/300gg-92","stext":{"head":"§300gg–92. Regulations","paras":[[0,"The Secretary, consistent with section 104 of the Health Care Portability and Accountability Act of 1996, may promulgate such regulations as may be necessary or appropriate to carry out the provisions of this subchapter. The Secretary may promulgate any interim final rules as the Secretary determines are appropriate to carry out this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/300gg-92?type=usc&year=mostrecent&link-type=html"},"head":"§300gg–92. Regulations","tname":"The Public Health and Welfare","by":{"0":"29","1":"39, 40","2":"11, 12"}},{"t":"usc","label":"42 U.S.C. § 2000bb","url":"https://www.law.cornell.edu/uscode/text/42/2000bb","stext":{"head":"§2000bb. Congressional findings and declaration of purposes","paras":[[0,"(a) Findings"],[0,"The Congress finds that—"],[1,"(1) the framers of the Constitution, recognizing free exercise of religion as an unalienable right, secured its protection in the First Amendment to the Constitution;"],[1,"(2) laws \"neutral\" toward religion may burden religious exercise as surely as laws intended to interfere with religious exercise;"],[1,"(3) governments should not substantially burden religious exercise without compelling justification;"],[1,"(4) in Employment Division v. Smith, 494 U.S. 872 (1990) the Supreme Court virtually eliminated the requirement that the government justify burdens on religious exercise imposed by laws neutral toward religion; and"],[1,"(5) the compelling interest test as set forth in prior Federal court rulings is a workable test for striking sensible balances between religious liberty and competing prior governmental interests."],[0,"(b) Purposes"],[0,"The purposes of this chapter are—"],[1,"(1) to restore the compelling interest test as set forth in Sherbert v. Verner, 374 U.S. 398 (1963) and Wisconsin v. Yoder, 406 U.S. 205 (1972) and to guarantee its application in all cases where free exercise of religion is substantially burdened; and"],[1,"(2) to provide a claim or defense to persons whose religious exercise is substantially burdened by government."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000bb?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2000bb. Congressional findings and declaration of purposes","tname":"The Public Health and Welfare","by":{"0":"9"}},{"t":"usc","label":"5 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/5/1002","subs":["(a)","(b)(6)"],"stext":{"head":"§1002. Findings and declarations","paras":[[0,"(a) Findings.—Congress finds that there are numerous committees, boards, commissions, councils, and similar groups which have been established to advise officers and agencies in the executive branch of the Federal Government and that they are frequently a useful and beneficial means of furnishing expert advice, ideas, and diverse opinions to the Federal Government."],[0,"(b) Findings and Declarations.—Congress further finds and declares that—"],[1,"(1) the need for many existing advisory committees has not been adequately reviewed;"],[1,"(2) new advisory committees should be established only when they are determined to be essential and their number should be kept to the minimum necessary;"],[1,"(3) advisory committees should be terminated when they are no longer carrying out the purposes for which they were established;"],[1,"(4) standards and uniform procedures should govern the establishment, operation, administration, and duration of advisory committees;"],[1,"(5) Congress and the public should be kept informed with respect to the number, purpose, membership, activities, and cost of advisory committees; and"],[1,"(6) the function of advisory committees should be advisory only, and all matters under their consideration should be determined, in accordance with law, by the official, agency, or officer involved."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/1002?type=usc&year=mostrecent&link-type=html"},"head":"§1002. Findings and declarations","tname":"Government Organization and Employees","by":{"0":"43, 43","1":"36"}},{"t":"usc","label":"5 U.S.C. § 7513","url":"https://www.law.cornell.edu/uscode/text/5/7513","subs":["(a)"],"stext":{"head":"§7513. Cause and procedure","paras":[[0,"(a) Under regulations prescribed by the Office of Personnel Management, an agency may take an action covered by this subchapter against an employee only for such cause as will promote the efficiency of the service."],[0,"(b) An employee against whom an action is proposed is entitled to—"],[1,"(1) at least 30 days' advance written notice, unless there is reasonable cause to believe the employee has committed a crime for which a sentence of imprisonment may be imposed, stating the specific reasons for the proposed action;"],[1,"(2) a reasonable time, but not less than 7 days, to answer orally and in writing and to furnish affidavits and other documentary evidence in support of the answer;"],[1,"(3) be represented by an attorney or other representative; and"],[1,"(4) a written decision and the specific reasons therefor at the earliest practicable date."],[0,"(c) An agency may provide, by regulation, for a hearing which may be in lieu of or in addition to the opportunity to answer provided under subsection (b)(2) of this section."],[0,"(d) An employee against whom an action is taken under this section is entitled to appeal to the Merit Systems Protection Board under section 7701 of this title."],[0,"(e) Copies of the notice of proposed action, the answer of the employee when written, a summary thereof when made orally, the notice of decision and reasons therefor, and any order effecting an action covered by this subchapter, together with any supporting material, shall be maintained by the agency and shall be furnished to the Board upon its request and to the employee affected upon the employee's request."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7513?type=usc&year=mostrecent&link-type=html"},"head":"§7513. Cause and procedure","tname":"Government Organization and Employees","by":{"0":"30","2":"7"}},{"t":"usc","label":"12 U.S.C. § 263","url":"https://www.law.cornell.edu/uscode/text/12/263","subs":["(b)"],"by":{"0":"25, 25"}},{"t":"usc","label":"26 U.S.C. § 7443A","url":"https://www.law.cornell.edu/uscode/text/26/7443A","subs":["(c)"],"by":{"0":"34"}},{"t":"usc","label":"39 U.S.C. § 203","url":"https://www.law.cornell.edu/uscode/text/39/203","stext":{"head":"§203. Postmaster General; Deputy Postmaster General","paras":[[0,"The chief executive officer of the Postal Service is the Postmaster General appointed under section 202(c) of this title. The alternate chief executive officer of the Postal Service is the Deputy Postmaster General appointed under section 202(d) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/39/203?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§203. Postmaster General; Deputy Postmaster General","tname":"Postal Service","by":{"0":"25"}},{"t":"usc","label":"42 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/42/202","stext":{"head":"§202. Administration and supervision of Service","paras":[[0,"The Public Health Service in the Department of Health and Human Services shall be administered by the Assistant Secretary for Health under the supervision and direction of the Secretary."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/202?type=usc&year=mostrecent&link-type=html"},"op":8,"ar":2,"head":"§202. Administration and supervision of Service","tname":"The Public Health and Welfare","by":{"0":"8, 28, 29, 41, 42","1":"10, 34, 37, 38, 39","2":"9-12, 14, 20"}},{"t":"usc","label":"42 U.S.C. § 299","url":"https://www.law.cornell.edu/uscode/text/42/299","subs":["(a)"],"stext":{"head":"§299. Mission and duties","paras":[[0,"(a) In general"],[0,"There is established within the Public Health Service an agency to be known as the Agency for Healthcare Research and Quality, which shall be headed by a director appointed by the Secretary. The Secretary shall carry out this subchapter acting through the Director."],[0,"(b) Mission"],[0,"The purpose of the Agency is to enhance the quality, appropriateness, and effectiveness of health services, and access to such services, through the establishment of a broad base of scientific research and through the promotion of improvements in clinical and health system practices, including the prevention of diseases and other health conditions. The Agency shall promote health care quality improvement by conducting and supporting—"],[1,"(1) research that develops and presents scientific evidence regarding all aspects of health care, including—"],[2,"(A) the development and assessment of methods for enhancing patient participation in their own care and for facilitating shared patient-physician decision-making;"],[2,"(B) the outcomes, effectiveness, and cost-effectiveness of health care practices, including preventive measures and long-term care;"],[2,"(C) existing and innovative technologies;"],[2,"(D) the costs and utilization of, and access to health care;"],[2,"(E) the ways in which health care services are organized, delivered, and financed and the interaction and impact of these factors on the quality of patient care;"],[2,"(F) methods for measuring quality and strategies for improving quality; and"],[2,"(G) ways in which patients, consumers, purchasers, and practitioners acquire new information about best practices and health benefits, the determinants and impact of their use of this information;"],[1,"(2) the synthesis and dissemination of available scientific evidence for use by patients, consumers, practitioners, providers, purchasers, policy makers, and educators; and"],[1,"(3) initiatives to advance private and public efforts to improve health care quality."],[0,"(c) Requirements with respect to rural and inner-city areas and priority populations"],[0,"(1) Research, evaluations and demonstration projects"],[1,"In carrying out this subchapter, the Director shall conduct and support research and evaluations, and support demonstration projects, with respect to—"],[2,"(A) the delivery of health care in inner-city areas, and in rural areas (including frontier areas); and"],[2,"(B) health care for priority populations, which shall include—"],[3,"(i) low-income groups;"],[3,"(ii) minority groups;"],[3,"(iii) women;"],[3,"(iv) children;"],[3,"(v) the elderly; and"],[3,"(vi) individuals with special health care needs, including individuals with disabilities and individuals who need chronic care or end-of-life health care."],[0,"(2) Process to ensure appropriate research"],[1,"The Director shall establish a process to ensure that the requirements of paragraph (1) are reflected in the overall portfolio of research conducted and supported by the Agency."],[0,"(3) Office of Priority Populations"],[1,"The Director shall establish an Office of Priority Populations to assist in carrying out the requirements of paragraph (1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/299?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§299. Mission and duties","tname":"The Public Health and Welfare","by":{"0":"8, 26","2":"17"}},{"t":"usc","label":"42 U.S.C. § 299b-4","url":"https://www.law.cornell.edu/uscode/text/42/299b-4","subs":["(a)","(a)(1)","(a)(5)","(a)(6)"],"stext":{"head":"§299b–4. Research supporting primary care and access in underserved areas","paras":[[0,"(a) Preventive Services Task Force"],[0,"(1) Establishment and purpose"],[1,"The Director shall convene an independent Preventive Services Task Force (referred to in this subsection as the \"Task Force\") to be composed of individuals with appropriate expertise. Such Task Force shall review the scientific evidence related to the effectiveness, appropriateness, and cost-effectiveness of clinical preventive services for the purpose of developing recommendations for the health care community, and updating previous clinical preventive recommendations, to be published in the Guide to Clinical Preventive Services (referred to in this section as the \"Guide\"), for individuals and organizations delivering clinical services, including primary care professionals, health care systems, professional societies, employers, community organizations, non-profit organizations, Congress and other policy-makers, governmental public health agencies, health care quality organizations, and organizations developing national health objectives. Such recommendations shall consider clinical preventive best practice recommendations from the Agency for Healthcare Research and Quality, the National Institutes of Health, the Centers for Disease Control and Prevention, the Institute of Medicine, specialty medical associations, patient groups, and scientific societies."],[0,"(2) Duties"],[1,"The duties of the Task Force shall include—"],[2,"(A) the development of additional topic areas for new recommendations and interventions related to those topic areas, including those related to specific sub-populations and age groups;"],[2,"(B) at least once during every 5-year period, review 1 interventions and update 2 recommendations related to existing topic areas, including new or improved techniques to assess the health effects of interventions;"],[2,"(C) improved integration with Federal Government health objectives and related target setting for health improvement;"],[2,"(D) the enhanced dissemination of recommendations;"],[2,"(E) the provision of technical assistance to those health care professionals, agencies and organizations that request help in implementing the Guide 3 recommendations; and"],[2,"(F) the submission of yearly reports to Congress and related agencies identifying gaps in research, such as preventive services that receive an insufficient evidence statement, and recommending priority areas that deserve further examination, including areas related to populations and age groups not adequately addressed by current recommendations."],[0,"(3) Role of Agency"],[1,"The Agency shall provide ongoing administrative, research, and technical support for the operations of the Task Force, including coordinating and supporting the dissemination of the recommendations of the Task Force, ensuring adequate staff resources, and assistance to those organizations requesting it for implementation of the Guide's recommendations."],[0,"(4) Coordination with Community Preventive Services Task Force"],[1,"The Task Force shall take appropriate steps to coordinate its work with the Community Preventive Services Task Force and the Advisory Committee on Immunization Practices, including the examination of how each task force's recommendations interact at the nexus of clinic and community."],[0,"(5) Operation"],[1,"Operation.4 In carrying out the duties under paragraph (2), the Task Force is not subject to the provisions of chapter 10 of title 5."],[0,"(6) Independence"],[1,"All members of the Task Force convened under this subsection, and any recommendations made by such members, shall be independent and, to the extent practicable, not subject to political pressure."],[0,"(7) Authorization of appropriations"],[1,"There are authorized to be appropriated such sums as may be necessary for each fiscal year to carry out the activities of the Task Force."],[0,"(b) Primary care research"],[0,"(1) In general"],[1,"There is established within the Agency a Center for Primary Care Research (referred to in this subsection as the \"Center\") that shall serve as the principal source of funding for primary care practice research in the Department of Health and Human Services. For purposes of this paragraph, primary care research focuses on the first contact when illness or health concerns arise, the diagnosis, treatment or referral to specialty care, preventive care, and the relationship between the clinician and the patient in the context of the family and community."],[0,"(2) Research"],[1,"In carrying out this section, the Center shall conduct and support research concerning—"],[2,"(A) the nature and characteristics of primary care practice;"],[2,"(B) the management of commonly occurring clinical problems;"],[2,"(C) the management of undifferentiated clinical problems; and"],[2,"(D) the continuity and coordination of health services."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/299b-4?type=usc&year=mostrecent&link-type=html"},"head":"§299b–4. Research supporting primary care and access in underserved areas","tname":"The Public Health and Welfare","by":{"0":"34, 34, 34, 34","1":"10, 22, 39, 40, 3, 26, 54, 3, 9, 10, 13, 15, 16, 17, 18, 19, 20, 23, 24, 29, 37, 38, 39, 40, 41, 48, 50, 54, 36, i, 3, 6, 8, 9, 10, 11, 12, 13, 15, 16, 17, 18, 19, 20, 21, 23, 24, 26, 27, 29, 30, 32, 35, 37, 38, 39, 40, 41, 45, 46, 47, 48, 50, 51, 53, 54","2":"19, 17-19, 1-3, 5, 6, 11, 13, 20-23"}},{"t":"reg","label":"45 C.F.R. § 147.130","url":"https://www.ecfr.gov/current/title-45/section-147.130","subs":["(b)(i)"],"by":{"0":"7"}},{"t":"case","label":"Animal Legal Defense Fund, Inc. v. Shalala","cite":"104 F.3d 424","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/104/424/","by":{"1":"36"}},{"t":"case","label":"Biden v. Nebraska","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"op":1,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"33, 40"}},{"t":"case","label":"Branch v. Smith","cite":"538 U.S. 254","y":2003,"id":"2002/01-1437","sc":1,"op":22,"sum":"The Court held, 9-0, that the District Court properly enjoined enforcement of the state- court plan that lacked the required timely preclearance.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"California v. Texas","cite":"593 U.S. 659","y":2021,"id":"2020/19-840","sc":1,"sum":"Plaintiffs lack standing to challenge the Patient Protection and Affordable Care Act’s minimum essential coverage provision.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"46"}},{"t":"case","label":"Chevron U.S.A., Inc. v. Natural Resources Defense Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Cleavinger v. Saxner","cite":"474 U.S. 193","y":1985,"id":"1985/84-732","sc":1,"sum":"Petitioners are entitled to only qualified immunity. Pp. 199-208. 727 F. 2d 669, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"Data Marketing Partnership, LP v. United States Dep’t of Labor","cite":"45 F.4th 846","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/45/846/","by":{"1":"6"}},{"t":"case","label":"FEC v. Ted Cruz for Senate","cite":"596 U.S. 289","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/289/","sc":1,"by":{"1":"49"}},{"t":"case","label":"Free Enterprise Fund v. Public Co. Accounting Oversight Bd.","cite":"537 F.3d 667","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/537/667/","by":{"1":"14"}},{"t":"case","label":"Gordon v. New York Stock Exchange, Inc.","cite":"422 U.S. 659","y":1975,"id":"1974/74-304","sc":1,"sum":"The Supreme Court held that the Securities and Exchange Act of 1934 impliedly repealed any applicable antitrust laws. The Act authorized the Securities and Exchange Commission as the sole regulator for the New York Stock Exchange. Justice William O. Douglas wrote a concurrence, stating that the SEC has actively exercised its authority so commission rates are monitored in the way Congress intended.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Grupo Mexicano de Desarrollo S.A. v. Alliance Bond Fund, Inc.","cite":"527 U.S. 308","y":1999,"id":"1998/98-231","sc":1,"sum":"The Court held that the District Court lacked the authority to issue a preliminary injunction preventing defendants being sued by creditors from disposing of their assets pending adjudication of the creditor's contract claim for monetary damages because such a remedy was historically unavailable from a court of equity.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Haaland v. Brackeen","cite":"599 U.S. 255","y":2023,"id":"2022/21-376","sc":1,"sum":"In child custody proceedings governed by the Indian Child Welfare Act, the Court affirms the Fifth Circuit’s conclusion that ICWA is consistent with Congress’s Article I authority, rejects petitioners’ anticommandeering challenges under the Tenth Amendment, and finds the parties lack standing to litigate their other challenges to ICWA’s placement preferences.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"47"}},{"t":"case","label":"(vi) Humphrey’s Executor v. United States","cite":"295 U.S. 602","y":1935,"id":"1900-1940/295us602","sc":1,"sum":"The unanimous Court found that the FTC Act was constitutional and that Humphrey's dismissal on policy grounds was unjustified. The Court reasoned that the Constitution had never given \"illimitable power of removal\" to the president. Justice Sutherland dismissed the government's main line of defense in this case which relied heavily on the Court's decision in Myers v. United States (1926).","sumSrc":"Oyez","by":{"1":"16, 20, 21"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Leavitt v. Jane L.","cite":"518 U.S. 137","y":1996,"id":"1995/95-1242","sc":1,"sum":"The anonymous Per Curiam opinion held that the Utah Legislature had explicitly stated that each of the two abortion provisions was meant to stand independent of the other. The Court called the Tenth Circuit's interpretation of the Utah legislature's intent \"questionable when considered in isolation\" and \"plainly error\" when considered in light of the statutory text.","sumSrc":"Oyez","by":{"1":"45–46"}},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"op":2,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"39"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Morales v. Trans World Airlines, Inc.","cite":"504 U.S. 374","y":1992,"id":"1991/90-1604","sc":1,"sum":"The Court held that the Airline Deregulation Act of 1978 prevents states from prohibiting deceptive airline fare advertisements through enforcement of their general consumer protection statuses.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"op":2,"sum":"The near-unanimous Court held that the means of selecting the independent counsel did not violate the Appointments Clause; the powers allocated to the special court did not violate Article III; and the Act was not offensive to the separation of powers doctrine since it did not impermissibly interfere with the functions of the Executive Branch.","sumSrc":"Oyez","by":{"1":"16, 21, 22"}},{"t":"case","label":"Novartis Pharmaceuticals Corp. v. Johnson","cite":"102 F.4th 452","y":2024,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/102/452/","sum":"Recognizing that the Secretary lacks a general grant of substantive rulemaking authority under the Public Health Service Act.","sumSrc":"brief:1","by":{"1":"31"}},{"t":"case","label":"Pharmaceutical Research and Manufacturers of America v. United States Dep’t of Health and Human Services","cite":"4 F. Supp. 3d 28","y":2014,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/4/28/","by":{"1":"31"}},{"t":"case","label":"Ryder v. United States","cite":"515 U.S 177","y":1995,"url":"https://www.courtlistener.com/c/U.S/515/177/","by":{"1":"45"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Environment","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"United States v. Perkins","cite":"116 U.S. 483","y":1886,"id":"scdb/1885-120","sc":1,"sum":"When Congress by law, vests the appointment of inferior officers in the heads of departments, it may limit and restrict the power of removal as it deems best for the public interests.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Uzuegbunam v. Preczewski","cite":"592 U.S. 279","y":2021,"id":"2020/19-968","sc":1,"sum":"A request for nominal damages satisfies the redressability element necessary for Article III standing where a plaintiff’s claim is based on a completed violation of a legal right.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"47"}},{"t":"case","label":"Whole Woman’s Health v. Hellerstedt","cite":"579 U.S. 582","y":2016,"id":"2015/15-274","sc":1,"sum":"The Court determined that the regulations at issue unconstitutionally imposed an undue burden on women seeking abortions because they created a substantial burden and did not actually serve the stated government interest.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"(vii) Whole Woman’s Health v. Jackson","cite":"595 U.S. 30","y":2021,"url":"https://supreme.justia.com/cases/federal/us/595/30/","sc":1,"by":{"1":"11, 47, 48"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(4)"],"stext":{"head":"§551. Definitions","paras":[[0,"For the purpose of this subchapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[1,"or except as to the requirements of section 552 of this title—"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1"],[1,"(2) \"person\" includes an individual, partnership, corporation, association, or public or private organization other than an agency;"],[1,"(3) \"party\" includes a person or agency named or admitted as a party, or properly seeking and entitled as of right to be admitted as a party, in an agency proceeding, and a person or agency admitted by an agency as a party for limited purposes;"],[1,"(4) \"rule\" means the whole or a part of an agency statement of general or particular applicability and future effect designed to implement, interpret, or prescribe law or policy or describing the organization, procedure, or practice requirements of an agency and includes the approval or prescription for the future of rates, wages, corporate or financial structures or reorganizations thereof, prices, facilities, appliances, services or allowances therefor or of valuations, costs, or accounting, or practices bearing on any of the foregoing;"],[1,"(5) \"rule making\" means agency process for formulating, amending, or repealing a rule;"],[1,"(6) \"order\" means the whole or a part of a final disposition, whether affirmative, negative, injunctive, or declaratory in form, of an agency in a matter other than rule making but including licensing;"],[1,"(7) \"adjudication\" means agency process for the formulation of an order;"],[1,"(8) \"license\" includes the whole or a part of an agency permit, certificate, approval, registration, charter, membership, statutory exemption or other form of permission;"],[1,"(9) \"licensing\" includes agency process respecting the grant, renewal, denial, revocation, suspension, annulment, withdrawal, limitation, amendment, modification, or conditioning of a license;"],[1,"(10) \"sanction\" includes the whole or a part of an agency—"],[2,"(A) prohibition, requirement, limitation, or other condition affecting the freedom of a person;"],[2,"(B) withholding of relief;"],[2,"(C) imposition of penalty or fine;"],[2,"(D) destruction, taking, seizure, or withholding of property;"],[2,"(E) assessment of damages, reimbursement, restitution, compensation, costs, charges, or fees;"],[2,"(F) requirement, revocation, or suspension of a license; or"],[2,"(G) taking other compulsory or restrictive action;"],[1,"(11) \"relief\" includes the whole or a part of an agency—"],[2,"(A) grant of money, assistance, license, authority, exemption, exception, privilege, or remedy;"],[2,"(B) recognition of a claim, right, immunity, privilege, exemption, or exception; or"],[2,"(C) taking of other action on the application or petition of, and beneficial to, a person;"],[1,"(12) \"agency proceeding\" means an agency process as defined by paragraphs (5), (7), and (9) of this section;"],[1,"(13) \"agency action\" includes the whole or a part of an agency rule, order, license, sanction, relief, or the equivalent or denial thereof, or failure to act; and"],[1,"(14) \"ex parte communication\" means an oral or written communication not on the public record with respect to which reasonable prior notice to all parties is not given, but it shall not include requests for status reports on any matter or proceeding covered by this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/551?type=usc&year=mostrecent&link-type=html"},"head":"§551. Definitions","tname":"Government Organization and Employees","by":{"1":"30–31","2":"14, 14"}},{"t":"usc","label":"5 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/5/1001","subs":["(2)(A)"],"by":{"1":"36"}},{"t":"usc","label":"15 U.S.C. § 7211","url":"https://www.law.cornell.edu/uscode/text/15/7211","subs":["(e)(4)(A)"],"by":{"1":"52"}},{"t":"usc","label":"21 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/21/371","subs":["(a)"],"by":{"1":"31"}},{"t":"usc","label":"28 U.S.C. § 1651","url":"https://www.law.cornell.edu/uscode/text/28/1651","subs":["(a)"],"by":{"1":"49"}},{"t":"usc","label":"28 U.S.C. § 2201","url":"https://www.law.cornell.edu/uscode/text/28/2201","by":{"1":"47"}},{"t":"usc","label":"35 U.S.C. § 6","url":"https://www.law.cornell.edu/uscode/text/35/6","subs":["(a)"],"by":{"1":"52, 53"}},{"t":"usc","label":"42 U.S.C. § 300gg-14","url":"https://www.law.cornell.edu/uscode/text/42/300gg-14","subs":["(b)"],"by":{"1":"31"}},{"t":"usc","label":"42 U.S.C. § 1302","url":"https://www.law.cornell.edu/uscode/text/42/1302","subs":["(a)"],"by":{"1":"31"}},{"t":"usc","label":"42 U.S.C. § 18011","url":"https://www.law.cornell.edu/uscode/text/42/18011","by":{"1":"2"}},{"t":"reg","label":"45 C.F.R. § 147.140","url":"https://www.ecfr.gov/current/title-45/section-147.140","by":{"1":"2"}},{"t":"reg","label":"Department of Health and Human Services, Short- Term, Limited-Duration Insurance, 83 Fed. Reg. 38,212","url":"https://www.govinfo.gov/link/fr/83/38212","by":{"1":"2"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"ar":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"op":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"580 U.S. 288","y":2017,"url":"https://supreme.justia.com/cases/federal/us/580/288/","sc":1,"op":5,"sum":"Concluding that when the President “ `direct[s]' ” someone to “ `perform the functions and duties' ” of an offce temporarily, “he is `appoint[ing]' that person as an `offcer of the United States' within the meaning of the Appointments Clause” even though the statute refers to “appointment[s]” to the same offces, 5 U. S. C. § 3345.","sumSrc":"opinion","by":{"2":"19"}},{"t":"case","label":"Shurtleff v. United States","cite":"189 U.S. 311","y":1903,"id":"scdb/1902-126","sc":1,"op":2,"sum":"Where Congress creates an office and provides for the removal of the incumbent at any time for inefficiency, neglect of duty, or malfeasance in office, if the removal of the officer is sought to be made for any of those causes he is entitled to notice and a hearing; but if the President removes him without giving him notice and an opportunity to defend himself, it must be presumed that the removal was not made for …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"United States v. Texas","cite":"599 U.S. 670","y":2023,"id":"2022/22-58","sc":1,"sum":"Texas and Louisiana lack Article III standing to challenge immigration-enforcement guidelines promulgated by the Secretary of Homeland Security that prioritize the arrest and removal of certain noncitizens from the United States.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"15"}},{"t":"case","label":"Willy v. Administrative Review Bd.","cite":"423 F.3d 483","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/423/483/","sum":"Holding that a similar Reorganization Plan for the Department of Labor authorized the Secretary of Labor to appoint certain inferior officers.","sumSrc":"brief:2","by":{"2":"18"}},{"t":"usc","label":"5 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/5/553","stext":{"head":"§553. Rule making","paras":[[0,"(a) This section applies, according to the provisions thereof, except to the extent that there is involved—"],[1,"(1) a military or foreign affairs function of the United States; or"],[1,"(2) a matter relating to agency management or personnel or to public property, loans, grants, benefits, or contracts."],[0,"(b) General notice of proposed rule making shall be published in the Federal Register, unless persons subject thereto are named and either personally served or otherwise have actual notice thereof in accordance with law. The notice shall include—"],[1,"(1) a statement of the time, place, and nature of public rule making proceedings;"],[1,"(2) reference to the legal authority under which the rule is proposed;"],[1,"(3) either the terms or substance of the proposed rule or a description of the subjects and issues involved; and"],[1,"(4) the Internet address of a summary of not more than 100 words in length of the proposed rule, in plain language, that shall be posted on the Internet website under section 206(d) of the E-Government Act of 2002 (44 U.S.C. 3501 note) (commonly known as regulations.gov)."],[0,"Except when notice or hearing is required by statute, this subsection does not apply—"],[1,"(A) to interpretative rules, general statements of policy, or rules of agency organization, procedure, or practice; or"],[1,"(B) when the agency for good cause finds (and incorporates the finding and a brief statement of reasons therefor in the rules issued) that notice and public procedure thereon are impracticable, unnecessary, or contrary to the public interest."],[0,"(c) After notice required by this section, the agency shall give interested persons an opportunity to participate in the rule making through submission of written data, views, or arguments with or without opportunity for oral presentation. After consideration of the relevant matter presented, the agency shall incorporate in the rules adopted a concise general statement of their basis and purpose. When rules are required by statute to be made on the record after opportunity for an agency hearing, sections 556 and 557 of this title apply instead of this subsection."],[0,"(d) The required publication or service of a substantive rule shall be made not less than 30 days before its effective date, except—"],[1,"(1) a substantive rule which grants or recognizes an exemption or relieves a restriction;"],[1,"(2) interpretative rules and statements of policy; or"],[1,"(3) as otherwise provided by the agency for good cause found and published with the rule."],[0,"(e) Each agency shall give an interested person the right to petition for the issuance, amendment, or repeal of a rule."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/553?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§553. Rule making","tname":"Government Organization and Employees","by":{"2":"14"}},{"t":"law","label":"Pub. L. No. 89-810","url":"https://www.govinfo.gov/link/statute/80/1610","by":{"2":"10, 11, 18, 20"}},{"t":"usc","label":"22 U.S.C. § 2651a","url":"https://www.law.cornell.edu/uscode/text/22/2651a","subs":["(a)(1)"],"stext":{"head":"§2651a. Organization of Department of State","paras":[[0,"(a) Secretary of State"],[0,"(1) The Department of State shall be administered, in accordance with this Act and other provisions of law, under the supervision and direction of the Secretary of State (hereinafter referred to as the \"Secretary\")."],[0,"(2) The Secretary, the Deputy Secretary of State, and the Deputy Secretary of State for Management and Resources shall be appointed by the President, by and with the advice and consent of the Senate."],[0,"(3)(A) Notwithstanding any other provision of law and except as provided in this section, the Secretary shall have and exercise any authority vested by law in any office or official of the Department of State. The Secretary shall administer, coordinate, and direct the Foreign Service of the United States and the personnel of the Department of State, except where authority is inherent in or vested in the President."],[0,"(B)(i) The Secretary shall not have the authority of the Inspector General or the Chief Financial Officer."],[0,"(ii) The Secretary shall not have any authority given expressly to diplomatic or consular officers."],[0,"(4) The Secretary is authorized to promulgate such rules and regulations as may be necessary to carry out the functions of the Secretary of State and the Department of State. Unless otherwise specified in law, the Secretary may delegate authority to perform any of the functions of the Secretary or the Department to officers and employees under the direction and supervision of the Secretary. The Secretary may delegate the authority to redelegate any such functions."],[0,"(b) Under Secretaries"],[0,"(1) In general"],[1,"There shall be in the Department of State not more than 6 Under Secretaries of State, who shall be appointed by the President, by and with the advice and consent of the Senate, and who shall be compensated at the rate provided for at level III of the Executive Schedule under section 5314 of title 5."],[0,"(2) Under Secretary for Arms Control and International Security"],[1,"There shall be in the Department of State, among the Under Secretaries authorized by paragraph (1), an Under Secretary for Arms Control and International Security, who shall assist the Secretary and the Deputy Secretary in matters related to international security policy, arms control, and nonproliferation. Subject to the direction of the President, the Under Secretary may attend and participate in meetings of the National Security Council in his role as Senior Advisor to the President and the Secretary of State on Arms Control and Nonproliferation Matters."],[0,"(3) Under Secretary for Public Diplomacy"],[1,"There shall be in the Department of State, among the Under Secretaries authorized by paragraph (1), an Under Secretary for Public Diplomacy, who shall have primary responsibility to assist the Secretary and the Deputy Secretary in the formation and implementation of United States public diplomacy policies and activities, including international educational and cultural exchange programs, information, and international broadcasting. The Under Secretary for Public Diplomacy shall—"],[2,"(A) prepare an annual strategic plan for public diplomacy in collaboration with overseas posts and in consultation with the regional and functional bureaus of the Department;"],[2,"(B) ensure the design and implementation of appropriate program evaluation methodologies;"],[2,"(C) provide guidance to Department personnel in the United States and overseas who conduct or implement public diplomacy policies, programs, and activities;"],[2,"(D) assist the United States Agency for International Development and the Broadcasting Board of Governors to present the policies of the United States clearly and effectively;"],[2,"(E) submit statements of United States policy and editorial material to the Broadcasting Board of Governors for broadcast consideration; and"],[2,"(F) coordinate the allocation and management of the financial and human resources for public diplomacy, including for—"],[3,"(i) the Bureau of Educational and Cultural Affairs;"],[3,"(ii) the Bureau of Global Public Affairs;"],[3,"(iii) the Office of Policy, Planning, and Resources for Public Diplomacy and Public Affairs;"],[3,"(iv) the Global Engagement Center; and"],[3,"(v) the public diplomacy functions within the regional and functional bureaus."],[0,"(4) Nomination of Under Secretaries"],[1,"Whenever the President submits to the Senate a nomination of an individual for appointment to a position in the Department of State that is described in paragraph (1), the President shall designate the particular Under Secretary position in the Department of State that the individual shall have."],[0,"(c) Assistant Secretaries"],[0,"(1) In general"],[1,"There shall be in the Department of State not more than 24 Assistant Secretaries of State who shall be compensated at the rate provided for at level IV of the Executive Schedule under section 5315 of title 5. Each Assistant Secretary of State shall be appointed by the President, by and with the advice and consent of the Senate, except that the appointments of the Assistant Secretary for Public Affairs and the Assistant Secretary for Administration shall not be subject to the advice and consent of the Senate."],[0,"(2) Assistant Secretary of State for Democracy, Human Rights, and Labor"],[1,"(A) There shall be in the Department of State an Assistant Secretary of State for Democracy, Human Rights, and Labor who shall be responsible to the Secretary of State for matters pertaining to human rights and humanitarian affairs (including matters relating to prisoners of war and members of the United States Armed Forces missing in action) in the conduct of foreign policy and such other related duties as the Secretary may from time to time designate. The Secretary of State shall carry out the Secretary's responsibility under section 2304 of this title through the Assistant Secretary."],[1,"(B) The Assistant Secretary of State for Democracy, Human Rights, and Labor shall maintain continuous observation and review all matters pertaining to human rights and humanitarian affairs (including matters relating to prisoners of war and members of the United States Armed Forces missing in action) in the conduct of foreign policy including the following:"],[2,"(i) Gathering detailed information regarding humanitarian affairs and the observance of and respect for internationally recognized human rights in each country to which requirements of sections 2151n and 2304 of this title are relevant."],[2,"(ii) Preparing the statements and reports to Congress required under section 2304 of this title."],[2,"(iii) Making recommendations to the Secretary of State and the Administrator of the Agency for International Development regarding compliance with sections 2151n and 2304 of this title, and as part of the Assistant Secretary's overall policy responsibility for the creation of United States Government human rights policy, advising the Administrator of the Agency for International Development on the policy framework under which section 2151n(e) projects are developed and consulting with the Administrator on the selection and implementation of such projects."],[2,"(iv) Performing other responsibilities which serve to promote increased observance of internationally recognized human rights by all countries."],[0,"(3) Assistant Secretary for International Narcotics and Law Enforcement Affairs"],[0,"(A) In general"],[2,"There is authorized to be in the Department of State an Assistant Secretary for International Narcotics and Law Enforcement Affairs, who shall be responsible to the Secretary of State for all matters, programs, and related activities pertaining to international narcotics, anti-crime, and law enforcement affairs in the conduct of foreign policy by the Department, including, as appropriate, leading the coordination of programs carried out by United States Government agencies abroad, and such other related duties as the Secretary may from time to time designate."],[0,"(B) Areas of responsibility"],[2,"The Assistant Secretary for International Narcotics and Law Enforcement Affairs shall maintain continuous observation and coordination of all matters pertaining to international narcotics, anti-crime, and law enforcement affairs in the conduct of foreign policy, including programs carried out by other United States Government agencies when such programs pertain to the following matters:"],[3,"(i) Combating international narcotics production and trafficking."],[3,"(ii) Strengthening foreign justice systems, including judicial and prosecutorial capacity, appeals systems, law enforcement agencies, prison systems, and the sharing of recovered assets."],[3,"(iii) Training and equipping foreign police, border control, other government officials, and other civilian law enforcement authorities for anti-crime purposes, including ensuring that no foreign security unit or member of such unit shall receive such assistance from the United States Government absent appropriate vetting."],[3,"(iv) Ensuring the inclusion of human rights and women's participation issues in law enforcement programs, in consultation with the Assistant Secretary for Democracy, Human Rights, and Labor, and other senior officials in regional and thematic bureaus and offices."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/2651a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2651a. Organization of Department of State","tname":"Foreign Relations and Intercourse","by":{"2":"10"}},{"t":"usc","label":"42 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/42/216","subs":["(b)"],"by":{"2":"11, 12"}},{"t":"usc","label":"42 U.S.C. § 289a-1","url":"https://www.law.cornell.edu/uscode/text/42/289a-1","subs":["(b)(5)(E)"],"by":{"2":"4"}},{"t":"usc","label":"42 U.S.C. § 7131","url":"https://www.law.cornell.edu/uscode/text/42/7131","by":{"2":"10"}}]};